import re, glob

# Find all SKILL.md files
files = glob.glob('skills/*/SKILL.md') + glob.glob('skills/*/references/*.md')
results = []
for f in files:
    try:
        txt = open(f).read()
    except:
        continue
    # Find bash blocks
    blocks = re.findall(r'```bash\n(.*?)```', txt, re.DOTALL)
    for block in blocks:
        lines = block.split('\n')
        for i, line in enumerate(lines):
            # bare grep -c/-n/-q without || true/echo guard, not in a if/conditional context
            if re.search(r'\bgrep -[cnq]', line) and '|| true' not in line and '|| echo' not in line and '|| :' not in line:
                # skip lines where grep is inside if [...]; then or similar conditional
                stripped = line.strip()
                if stripped.startswith('#'):
                    continue
                results.append(f'{f}: {stripped[:120]}')
if results:
    for r in results[:30]:
        print(r)
else:
    print("No bare grep calls found in Bash blocks")
PYEOF
